SELECT count() AS ticks, avg((bp + ap) / 2) AS avg_mid, stddevPop((bp + ap) / 2) AS mid_volatility, avg(ap - bp) AS avg_spread, stddevPop(ap - bp) AS spread_volatility, skewPop(ap - bp) AS spread_skew, kurtPop(ap - bp) AS spread_kurtosis, max(ap - bp) AS max_spread, corr(ap - bp, bs + `as`) AS corr_spread_depth, avg((toFloat64(bs) - toFloat64(`as`)) / nullIf(bs + `as`, 0)) AS avg_book_imbalance, quantilesTDigest(0.95, 0.99)(ap - bp) AS spread_p95_p99 FROM quotes WHERE sym = 'AAPL' LIMIT 1000000 SETTINGS max_threads=16,enable_filesystem_cache=0,use_page_cache_with_distributed_cache=0,force_read_through_distributed_cache=0,use_uncompressed_cache=0,use_query_cache=0,enable_parallel_replicas=0,max_parallel_replicas=1,log_queries=1,log_query_settings=1,log_queries_probability=1,log_queries_min_query_duration_ms=0,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=1000000000,max_bytes_to_read=100000000000,max_result_rows=1000000,result_overflow_mode='throw',log_comment='reader-cache-20261011T104032Z-measured' FORMAT Null
